const fs = require('fs');
const path = require('path');
const config = $('Load Daily Config').first().json || {};
if (!config.import_root) throw new Error('import_root 未配置');
const root = path.resolve(String(config.import_root));
fs.mkdirSync(root, { recursive: true });
for (const rel of ['inbox','processing','.locks/intake','.locks/jobs','system-errors']) fs.mkdirSync(path.join(root, rel), { recursive: true });
const rootReal = fs.realpathSync(root);
const jobs = $('Get Jobs for Recovery').all().map((item) => item.json).filter((row) => row && row.task_id);
const known = new Set(jobs.map((row) => String(row.task_id)));
const output = [];
const inbox = path.join(rootReal, 'inbox');
const candidates = fs.readdirSync(inbox, { withFileTypes: true })
  .filter((entry) => entry.isDirectory() && /^[A-Za-z0-9._-]+$/.test(entry.name))
  .map((entry) => entry.name).sort();
for (const folderName of candidates) {
  const dir = path.join(inbox, folderName);
  const storeReadyDir = path.join(dir, '.store-ready');
  const hasStorePublicationMarker = fs.existsSync(storeReadyDir)
    && fs.statSync(storeReadyDir).isDirectory()
    && fs.readdirSync(storeReadyDir, { withFileTypes: true }).some((entry) => entry.isFile() && /^[a-f0-9-]{36}\.json$/i.test(entry.name));
  if (!hasStorePublicationMarker && fs.existsSync(path.join(dir, '_READY')) && fs.existsSync(path.join(dir, 'product.json'))) {
    output.push({ source: 'schedule', folderName, priority: 10 });
  }
}
const processing = path.join(rootReal, 'processing');
for (const entry of fs.readdirSync(processing, { withFileTypes: true })) {
  if (!entry.isDirectory() || !/^[A-Za-z0-9._-]+__r\d+$/.test(entry.name) || known.has(entry.name)) continue;
  const dir = path.join(processing, entry.name);
  if (fs.existsSync(path.join(dir, '.intake.json')) && fs.existsSync(path.join(dir, 'product.json'))) {
    output.push({ source: 'recovery', folderName: entry.name, priority: 50 });
  }
}
const max = Math.max(1, Math.min(100, Number(config.max_daily_styles || 100)));
return output.slice(0, max).map((item) => ({ json: item }));

